CREATE   PROCEDURE [dbo].[YARD_DELETE]
( 
    @YardID BIGINT,
    @DeletedBy BIGINT = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        UPDATE ESS_MST_YARD
        SET IsDelete = 1,
            DeletedBy = @DeletedBy,
            DeletedDate = GETDATE()
        WHERE YardID = @YardID;
        
        SELECT @@ROWCOUNT AS RowsAffected;
    END TRY
    BEGIN CATCH
        SELECT ERROR_MESSAGE() AS ErrorMessage,
               ERROR_LINE() AS ErrorLine,
               ERROR_NUMBER() AS ErrorNumber;
    END CATCH
END

CREATE PROCEDURE [dbo].[YARD_INSERT]
(
    @PlantID BIGINT = NULL,
    @YardName VARCHAR(100) = NULL,
    @YardCode VARCHAR(50) = NULL,
    @YardTypeID BIGINT = NULL,
    @LatLong VARCHAR(100) = NULL,
    @Polygon GEOMETRY = NULL,
    @IsActive BIT = 1,
    @IsDelete BIT = 0,
    @CreatedBy BIGINT = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        INSERT INTO ESS_MST_YARD
        (
            PlantID,
            YardName,
            YardCode,
            YardTypeID,
            LatLong,
            Polygon,
            IsActive,
            CreatedBy,
            CreatedDate
        )
        VALUES
        (
            @PlantID,
            @YardName,
            @YardCode,
            @YardTypeID,
            @LatLong,
            @Polygon,
            @IsActive,
            @CreatedBy,
            GETDATE()
        );
        
        SELECT SCOPE_IDENTITY() AS InsertedID;
    END TRY
    BEGIN CATCH
        SELECT ERROR_MESSAGE() AS ErrorMessage,
               ERROR_LINE() AS ErrorLine,
               ERROR_NUMBER() AS ErrorNumber;
    END CATCH
END

CREATE   PROCEDURE [dbo].[YARD_UPDATE]
(
    @YardID BIGINT,
    @PlantID BIGINT = NULL,
