    @YardCode VARCHAR(50) = NULL,
    @YardTypeID BIGINT = NULL,
    @LatLong VARCHAR(100) = NULL,
    @Polygon GEOMETRY = NULL,
    @IsActive BIT = 1,
    @ModifiedBy BIGINT = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        UPDATE ESS_MST_YARD
        SET PlantID = @PlantID,
            YardName = @YardName,
            YardCode = @YardCode,
            YardTypeID = @YardTypeID,
            LatLong = @LatLong,
            Polygon = @Polygon,
